SELECT SUM(CASE WHEN o.device_type = 'android' OR o.device_type = 'ios' THEN 1 ELSE 0 END) * 1.0 / COUNT(*) FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-11-01 00:00:00' AND o.order_at < TIMESTAMP '2024-12-01 00:00:00'
